<body>
<header>
  <h1>Éditeur de Photos Pro</h1>
  <div style="display:flex; gap:10px;">
    <button class="btn-secondary" onclick="resetImage()">Réinitialiser</button>
    <button onclick="downloadImage()">Télécharger</button>
  </div>
</header>
<div class="main">
  <sidebar>
    <div id="upload-section" class="group">
      <label>Importer une image</label>
      <div class="dropzone" onclick="document.getElementById('file-input').click()">
        Glissez une image ici ou cliquez
      </div>
      <input type="file" id="file-input" accept="image/*" style="display:none" onchange="loadImage(event)">
    </div>
    <div class="group">
      <label>Luminosité <span id="val-brightness">100</span>%</label>
      <input type="range" id="brightness" min="0" max="200" value="100" oninput="applyFilters()">
    </div>
    <div class="group">
      <label>Contraste <span id="val-contrast">100</span>%</label>
      <input type="range" id="contrast" min="0" max="200" value="100" oninput="applyFilters()">
    </div>
    <div class="group">
      <label>Saturation <span id="val-saturation">100</span>%</label>
      <input type="range" id="saturation" min="0" max="200" value="100" oninput="applyFilters()">
    </div>
    <div class="group">
      <label>Flou <span id="val-blur">0</span>px</label>
      <input type="range" id="blur" min="0" max="20" value="0" oninput="applyFilters()">
    </div>
  </sidebar>
  <div class="workspace">
    <canvas id="canvas"></canvas>
  </div>
</div>
<script>
  const canvas = document.getElementById('canvas');
  const ctx = canvas.getContext('2d');
  let img = new Image();
  let originalPixels = null;

  function loadImage(e) {
    const reader = new FileReader();
    reader.onload = function(event) {
      img.onload = function() {
        canvas.width = img.width;
        canvas.height = img.height;
        ctx.drawImage(img, 0, 0);
        originalPixels = ctx.getImageData(0, 0, canvas.width, canvas.height);
      }
      img.src = event.target.result;
    }
    reader.readAsDataURL(e.target.files[0]);
  }

  function applyFilters() {
    if (!originalPixels) return;
    const b = document.getElementById('brightness').value;
    const c = document.getElementById('contrast').value;
    const s = document.getElementById('saturation').value;
    const bl = document.getElementById('blur').value;

    document.getElementById('val-brightness').innerText = b;
    document.getElementById('val-contrast').innerText = c;
    document.getElementById('val-saturation').innerText = s;
    document.getElementById('val-blur').innerText = bl;

    ctx.filter = `brightness(${b}%) contrast(${c}%) saturate(${s}%) blur(${bl}px)`;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(img, 0, 0);
  }

  function resetImage() {
    if (!originalPixels) return;
    ['brightness', 'contrast', 'saturation'].forEach(id => document.getElementById(id).value = 100);
    document.getElementById('blur').value = 0;
    applyFilters();
  }

  function downloadImage() {
    if (!originalPixels) return;
    const link = document.createElement('a');
    link.download = 'edited-photo.png';
    link.href = canvas.toDataURL();
    link.click();
  }

  // Image par défaut pour test immédiat
  img.onload = function() {
    canvas.width = img.width;
    canvas.height = img.height;
    ctx.drawImage(img, 0, 0);
    originalPixels = ctx.getImageData(0, 0, canvas.width, canvas.height);
  };
  img.src = 'https://images.unsplash.com/photo-1579546929518-9e396f3cc809?w=800';
</script>
